const $=s=>document.querySelector(s), canvas=$('#world'),g=canvas.getContext('2d'),fmt=n=>'₺'+Math.round(n).toLocaleString('tr-TR');
const MENU=[{name:'Soslu Tavuk',price:120,color:'#f3b75b'},{name:'Adana Dürüm',price:150,color:'#a65b37'},{name:'Çıtır Tavuk',price:130,color:'#e19c38'}];
const STAFF_NAMES=['Tolga','Emrecan','Fatih','Can','Burak','Mücahit','Doğukan','Murat'];
let account={cash:800,day:1,stock:24,speed:0,grill:0,deco:0,ad:0,total:0,employees:[],menu:[0,1,2],xp:0,earned:0,camera:0,coffee:0,lighting:0,fridge:0,jukebox:0,dishwasher:0};try{let q=JSON.parse(localStorage.getItem('durumle-world-v2'));if(q&&Number.isFinite(q.cash))account={...account,...q}}catch{}
if(account.employees?.length)account.employees=account.employees.map((employee,index)=>({...employee,name:STAFF_NAMES[index%STAFF_NAMES.length]}));
let W=innerWidth,H=innerHeight,DPR=1,zoom=1,cam={x:550,y:445},time=180,started=false,paused=false,served=0,missed=0,revenue=0,spawnIn=1,customers=[],particles=[],jobs=[],carrying=null,orderId=0,elapsed=0,nearest=null,sound=false,audio=null,keys={},joy={x:0,y:0},target=null,autointeract=null,last=performance.now(),hudClock=0;
const player={x:550,y:520,walk:0,dir:1,shirt:'#e24836',skin:'#eab58d',hair:'#53382b',chef:true};
const tables=[{x:285,y:405,id:0},{x:815,y:405,id:1},{x:285,y:590,id:2},{x:815,y:590,id:3}];
const stations=[{id:'sink',x:720,y:260,tx:720,ty:320,label:'Bulaşıkları yıka'},{id:'till',x:650,y:725,tx:650,ty:680,label:'Kasada ödeme al'},{id:'grill',x:480,y:270,tx:480,ty:320,label:'Dürüm tezgâhı'},{id:'stock',x:185,y:270,tx:185,ty:325,label:'Stok deposu'},{id:'office',x:880,y:265,tx:880,ty:325,label:'Şube bilgisayarı'},{id:'ad',x:920,y:720,tx:860,ty:725,label:'Reklam panosu'}];
const obstacles=[{x:125,y:190,w:850,h:90},...tables.map(t=>({x:t.x-62,y:t.y-36,w:124,h:72})),{x:898,y:685,w:47,h:64}];
const combo=new ComboSystem(),tasks=new TaskBoard();
let saveElapsed=0,cleanPlates=8,sinkDirty=0,tableDishes={},playerWork=null,paid=0,register=null,registerCounted=[],changeGiven=[],discountApplied=false,burned=0,fastServes=0,cleanedTables=0;let staff=[],dirty=new Set(),spawned=0,dayCosts={food:0,waste:0,coffee:0,repairs:0},dailyTips=0,catches=new Set(),shake=0,prepBoost=0,cleanClock=0;
function staffEvent(ev){if(['slacking','caught','break','fired'].includes(ev.to))tasks.release(ev.id);if(ev.to==='slacking'){let p=staff.find(x=>x.brain.id===ev.id);if(p){p.task=null;p.path=[];floater(p.x,p.y-75,'Kaytarıyor!','#ffe3ab')}}}
function makeStaff(def){return {x:650,y:680,walk:0,dir:1,shirt:def.role==='cook'?'#e8e0bd':'#648fa2',skin:'#e2ac80',hair:'#44382d',brain:new Employee(def,{onEvent:staffEvent}),path:[],task:null,carried:null,timer:0}}
staff=(account.employees??[]).map(makeStaff);
function save(){account.session=started?{time,served,missed,revenue,spawnIn,spawned,customers,jobs,cleanPlates,sinkDirty,tableDishes,paid,burned,fastServes,cleanedTables,carrying,orderId,player:{x:player.x,y:player.y},dirty:[...dirty],dayCosts,dailyTips,catches:[...catches],combo:{count:combo.count,fever:combo.fever},staff:staff.map(p=>({id:p.brain.id,x:p.x,y:p.y,carried:p.carried}))}:null;account.employees=staff.map(p=>p.brain.snapshot());try{localStorage.setItem('durumle-world-v2',JSON.stringify(account))}catch{}}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function tone(freq=550){if(!sound)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();let osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(freq,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(freq*1.4,audio.currentTime+.13);gain.gain.setValueAtTime(.08,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.22)}catch{}}
function modal(html){clearInput();$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal()}
function closeModal(){$('#dialog').close();keys={};last=performance.now()}
function button(text,action,disabled=false,secondary=false){return `<button data-do="${action}" ${disabled?'disabled':''} class="${secondary?'secondary':''}">${text}</button>`}
function welcome(){modal(`<div class="eyebrow">KADIKÖY · MOBİL SÜRÜM 5</div><div class="hero-icon">👨‍🍳</div><h1>Küçük dükkân.<br>Büyük lezzet.</h1><p>Bu şubenin ustası sensin. Üç gözlü ızgarayı yönet, personel al, tabakları yıka ve kasada ödemeleri tamamla. İlk garsonun ücretsiz.</p><div class="tips"><b>Bilgisayar:</b> WASD / ok tuşları + E<br><b>Telefon:</b> Joystick + sarı etkileşim düğmesi<br><b>Kolay kontrol:</b> Zemine veya istasyona dokun, karakter yürüsün.</div>${button(account.session?'Açık vardiyaya devam et →':account.day+'. günün hazırlığı →',account.session?'restore':'morning')}<p style="font-size:10px">Dürümle’den ilham alan bağımsız hayran oyunu. Fiyatlar kurgusaldır.</p>`)}
function startDay(){closeModal();$('#kitchen-panel').hidden=true;$('#register-panel').hidden=true;cleanPlates=8;sinkDirty=0;tableDishes={};paid=0;burned=0;fastServes=0;cleanedTables=0;playerWork=null;register=null;tasks.tasks.clear();dirty.clear();spawned=0;dayCosts={food:0,waste:0,coffee:0,repairs:0};dailyTips=0;catches.clear();combo.count=0;combo.fever=0;for(let p of staff){p.task=null;p.carried=null;p.path=[];p.x=650;p.y=680;p.brain.runtime.fatigue=Math.max(0,p.brain.runtime.fatigue-40);if(p.brain.runtime.state!=='fired')p.brain.transition('idle',{cooldown:10,slackBehavior:null});} started=true;paused=false;time=180;served=0;missed=0;revenue=0;spawnIn=1;customers=[];carrying=null;jobs=[];target=null;autointeract=null;player.x=550;player.y=520;addCustomer();updateHUD();toast('Hoş geldin usta! ? işaretli müşteriye yaklaş.');save()}
function endDay(){started=false;const goal=dayPlan(account.day).target,bonus=paid>=goal?250:0;
 const wages=staff.filter(p=>p.brain.runtime.state!=='fired'&&p.brain.runtime.shift!=='off').reduce((n,p)=>n+p.brain.contract.wage*(p.brain.runtime.shift==='full'?1:.6),0);
 const dailyReward=missed===0&&catches.size>=2?150:0;account.cash+=bonus+dailyReward-wages-100;account.ad=Math.max(0,account.ad-1);account.xp+=served*10+(dailyReward?40:0);if(paid>=goal)account.day++;
 let report=ledger({sales:revenue-dailyTips,tips:dailyTips,...dayCosts,wages,rent:100,bonus:bonus+dailyReward});account.lastReport=report;save();
 modal('<div class="eyebrow">GECE KAPANIŞI · '+(paid>=goal?'BÖLÜM GEÇİLDİ':'HEDEF TUTMADI — AYNI GÜNÜ TEKRAR DENE')+'</div><h2>'+ (bonus?'Mahallenin yıldızısın!':'Eline sağlık, usta!') +'</h2><div class="summary">'+[['Servis / ödeme',served+' / '+paid],['Satış',fmt(report.sales)],['Bahşiş',fmt(dailyTips)],['Malzeme / israf',fmt(report.food)+' / '+fmt(report.waste)],['Maaş / kira',fmt(wages)+' / ₺100'],['Kahve / onarım',fmt(report.coffee)+' / '+fmt(report.repairs)],['Hedef ve görev primi',fmt(report.bonus)],['Faaliyet kârı',fmt(report.net)]].map(([a,b])=>'<div><small>'+a+'</small><b>'+b+'</b></div>').join('')+'</div><p>'+missed+' kayıp müşteri · '+catches.size+' farklı çalışan yakalandı · +'+(served*10)+' servis XP.<br>Yorum: “'+(missed?'Lezzet güzel ama biraz bekledik.':'Hızlı servis, sıcacık dürüm!')+'”</p><p style="font-size:11px">Malzeme stok alırken kasadan ödenir; burada tüketim maliyeti gösterilir, ikinci kez tahsil edilmez. Yatırımlar faaliyet kârına dahil değildir.</p>'+button('Sabah hazırlığı →','morning')+button('Yatırımları incele','office',false,true))}
function blocked(x,y){if(x<120||x>980||y<290||y>790)return true;return obstacles.some(o=>x>o.x-15&&x<o.x+o.w+15&&y>o.y-12&&y<o.y+o.h+12)}
function findPath(sx,sy,ex,ey){const unit=20,cols=55,rows=42,start=[Math.round(sx/unit),Math.round(sy/unit)],end=[Math.round(ex/unit),Math.round(ey/unit)],key=(x,y)=>y*cols+x;let queue=[start],seen=new Set([key(...start)]),prev=new Map(),head=0,found=null;while(head<queue.length&&head<2400){const [x,y]=queue[head++];if(Math.hypot(x-end[0],y-end[1])<1.5){found=[x,y];break}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){let nx=x+dx,ny=y+dy,k=key(nx,ny);if(nx<0||nx>=cols||ny<0||ny>=rows||seen.has(k)||blocked(nx*unit,ny*unit))continue;seen.add(k);prev.set(k,[x,y]);queue.push([nx,ny])}}if(!found)return [];let path=[],p=found;while(p&&(p[0]!==start[0]||p[1]!==start[1])){path.push({x:p[0]*unit,y:p[1]*unit});p=prev.get(key(...p))}return path.reverse()}
function move(p,dx,dy){if(!blocked(p.x+dx,p.y))p.x+=dx;if(!blocked(p.x,p.y+dy))p.y+=dy;if(dx||dy){p.walk+=Math.hypot(dx,dy)*.11;if(Math.abs(dx)>.1)p.dir=dx>0?1:-1}}
function follow(p,path,speed,dt){if(!path?.length)return false;let n=path[0],d=Math.hypot(n.x-p.x,n.y-p.y);if(d<5){path.shift();return true}let step=Math.min(d,speed*dt);move(p,(n.x-p.x)/d*step,(n.y-p.y)/d*step);return true}
function leave(c){if(c.state==='eating')dirtyTable(c);c.state='leaving';c.path=findPath(c.x,c.y,550,785)}
function candidates(){return [...stations,...staff.filter(p=>p.brain.runtime.state==='slacking').map(p=>({id:'staff',x:p.x,y:p.y,tx:p.x,ty:p.y,p,label:'Suçüstü yakala: '+p.brain.name})),...tables.filter(t=>dirty.has(t.id)).map(t=>({id:'clean',x:t.x,y:t.y,tx:t.x+(t.x<550?96:-96),ty:t.y+12,table:t.id,label:'Masayı temizle'})),...customers.filter(c=>['waiting','ordered'].includes(c.state)).map(c=>({id:'customer',x:c.x,y:c.y,tx:c.x,ty:c.y,c,label:c.state==='waiting'?'Sipariş al':carrying===c.recipe?'Dürümü servis et':MENU[c.recipe].name+' bekliyor'}))]}
function getNear(){return candidates().map(t=>({...t,d:Math.hypot(player.x-t.tx,player.y-t.ty)})).filter(t=>t.d<88).sort((a,b)=>a.d-b.d)[0]??null}
function interact(t=nearest){if(!started||paused||$('#dialog').open||!t)return;if(t.id==='staff'){catchStaff(t.p);return}if(t.id==='clean'){beginCleaning(t.table);return}if(t.id==='customer'){let c=t.c;if(c.state==='waiting'){c.state='ordered';tone(520);toast(MENU[c.recipe].name+' istiyor. Mutfak tezgâhına git.');floater(c.x,c.y-60,'Sipariş alındı','#fff4bd')}else if(c.state==='ordered'&&carrying===c.recipe){if(deliver(c,player))carrying=null;}else toast(carrying!==null?'Bu müşterinin siparişi farklı.':'Önce mutfaktan '+MENU[c.recipe].name+' hazırla.')}else if(t.id==='grill')openKitchen();else if(t.id==='sink')beginWashing();else if(t.id==='till')openRegister();else if(t.id==='office')management();else if(t.id==='stock')stock();else if(t.id==='ad')advert();updateHUD()}
function openKitchen(){clearInput();$('#register-panel').hidden=true;register=null;$('#kitchen-panel').hidden=false;renderKitchen();syncSheet()}
function grillSlots(){return 3}
function startCooking(recipe){if(!started||!account.menu.includes(recipe)||account.stock<1||jobs.length>=grillSlots())return false;let slot=[0,1,2].find(i=>!jobs.some(j=>j.slot===i));let duration=Math.max(2.5,5.5-account.grill*.8-(prepBoost>0?.8:0));prepBoost=Math.max(0,prepBoost-1);jobs.push({id:++orderId,slot,recipe,remaining:duration,full:duration,age:0,burnt:false});account.stock--;dayCosts.food+=20;tone(300);renderKitchen();save();return true}
function takeCooked(id,server=player){let j=jobs.find(j=>j.id===id);if(!j||j.remaining>0||j.burnt||(server===player?carrying!==null:server.carried!==null))return false;if(server===player)carrying=j.recipe;else server.carried=j.recipe;jobs=jobs.filter(x=>x!==j);renderKitchen();save();return true}
function discardBurnt(id){let j=jobs.find(j=>j.id===id&&j.burnt);if(!j)return false;jobs=jobs.filter(x=>x!==j);renderKitchen();return true}
function renderKitchen(){if($('#kitchen-panel').hidden)return;const signature=JSON.stringify([jobs.map(j=>[j.id,j.slot,j.burnt,j.remaining<=0]),carrying,account.stock,account.menu,customers.filter(c=>c.state==='ordered').map(c=>c.recipe)]);if(renderKitchen.lastKey===signature){for(let j of jobs){let el=$('#burner-timer-'+j.slot);if(el)el.textContent=j.remaining>0?Math.ceil(j.remaining)+' sn pişiyor':Math.max(0,Math.ceil(12+account.grill*3-j.age))+' sn sonra yanar'}return}renderKitchen.lastKey=signature;$('#kitchen-body').innerHTML='<div class="live-title"><b>3 GÖZLÜ IZGARA</b><span>Servis devam ediyor</span><button data-do="kitchen-close" aria-label="Ocağı kapat">×</button></div><div class="burners">'+[0,1,2].map(slot=>{let j=jobs.find(j=>j.slot===slot);return '<div class="burner '+(j?.burnt?'burnt':j?.remaining<=0?'ready':'')+'"><small>GÖZ '+(slot+1)+'</small><b>'+(j?MENU[j.recipe].name:'Boş')+'</b>'+(j?(j.burnt?button('Yandı · temizle','burn-'+j.id):j.remaining>0?'<span id="burner-timer-'+slot+'">'+Math.ceil(j.remaining)+' sn pişiyor</span>':button('Dürümü al <small id="burner-timer-'+slot+'">'+Math.max(0,Math.ceil(12+account.grill*3-j.age))+' sn sonra yanar</small>','take-'+j.id,carrying!==null)):'<span>Tarife dokun</span>')+'</div>'}).join('')+'</div><div class="cook-buttons">'+account.menu.map(i=>button(MENU[i].name+'<small>'+customers.filter(c=>c.state==='ordered'&&c.recipe===i).length+' sipariş bekliyor</small>','cook-'+i,jobs.length>=3||account.stock<1)).join('')+'</div><p>Stok '+account.stock+' · Hazır ürünleri zamanında al. Elindeki dürümü servis ederek boşalt.</p>'}
function updateCooking(dt){for(let j of jobs){if(j.burnt)continue;if(j.remaining>0){j.remaining-=dt;if(j.remaining<=0){tone(700);floater(425+j.slot*55,180,'Hazır!','#e8f6bf')}}else{j.age+=dt;if(j.age>12+account.grill*3){j.burnt=true;dayCosts.food=Math.max(0,dayCosts.food-20);dayCosts.waste+=20;burned++;combo.fail();shake=4;toast('Izgarada ürün yandı! Gözü temizle.')}}}}

function office(){modal(`<div class="eyebrow">ŞUBE BİLGİSAYARI</div><h2>Bir sonraki seviyeye.</h2><p>Kasanda ${fmt(account.cash)} var. Geliştirmeler kalıcıdır.</p>${button('Rahat ayakkabılar · '+fmt(250+account.speed*200)+'<small>Hareket hızını artır. Seviye '+account.speed+'/3</small>','buy-speed',account.speed>=3||account.cash<250+account.speed*200)}${button('Güçlü ızgara · '+fmt(300+account.grill*250)+'<small>Pişirme süresini kısalt. Seviye '+account.grill+'/3</small>','buy-grill',account.grill>=3||account.cash<300+account.grill*250)}${button('Konforlu şube · '+fmt(220+account.deco*180)+'<small>Müşteri sabrı +20 saniye. Seviye '+account.deco+'/3</small>','buy-deco',account.deco>=3||account.cash<220+account.deco*180)}${button(started?'Dükkâna dön':'Yeni güne başla',started?'close':'start',false,true)}`)}
function stock(){modal(`<div class="eyebrow">TEDARİK KÖŞESİ</div><h2>Depoyu dolduralım.</h2><p>${account.stock} porsiyon malzemen var. Her dürüm bir porsiyon tüketir.</p>${button('+12 porsiyon · ₺240','stock-buy',account.cash<240||account.stock+12>48+account.fridge*24)}${account.cash<240&&account.stock<3?button('Mahalle desteği · 6 porsiyon hediye','rescue'):''}${button('Dükkâna dön','close',false,true)}`)}
function advert(){modal(`<div class="eyebrow">MAHALLE SENİ KONUŞSUN</div><h2>Biraz ses getirelim.</h2><p>Yerel sosyal medya reklamı, 2 vardiya boyunca müşteri geliş aralığını kısaltır. Bu oyun içi bir kampanyadır.</p>${button(account.ad?account.ad+' vardiya aktif':'Kampanyayı başlat · ₺200','ad-buy',account.ad>0||account.cash<200)}${button('Dükkâna dön','close',false,true)}`)}
document.addEventListener('click',e=>{let b=e.target.closest('[data-do]');if(!b||b.disabled)return;let a=b.dataset.do;if(a==='restore')restoreSession();if(a==='start')startDay();if(a==='morning')morning();if(a==='close')closeModal();if(a==='office')management();if(a==='discard'){if(carrying!==null){dayCosts.food=Math.max(0,dayCosts.food-20);dayCosts.waste+=20;}carrying=null;closeModal()}if(a.startsWith('cook-'))startCooking(Number(a.slice(5)));if(a.startsWith('take-'))takeCooked(Number(a.slice(5)));if(a.startsWith('burn-'))discardBurnt(Number(a.slice(5)));if(a==='kitchen-close'){$('#kitchen-panel').hidden=true;syncSheet();}if(a.startsWith('buy-')){let k=a.split('-')[1],cost=k==='speed'?250+account[k]*200:k==='grill'?300+account[k]*250:220+account[k]*180;if(account.cash>=cost&&account[k]<3){account.cash-=cost;account[k]++;tone(800);office()}}if(a==='stock-buy'&&account.cash>=240&&account.stock+12<=48+account.fridge*24){account.cash-=240;account.stock+=12;stock();tone(600)}if(a==='rescue'&&account.cash<240&&account.stock<3){account.stock+=6;stock()}if(a==='ad-buy'&&account.cash>=200&&!account.ad){account.cash-=200;account.ad=2;advert();tone(600)}if(a==='resume'){paused=false;closeModal()}if(a==='guide'){modal(`<h2>Ustalığın yolu</h2><p>① Masaya gelen müşterinin yanına yürü, E ile sipariş al.<br>② Arka duvardaki kırmızı ızgaraya git. Tarifi seç.<br>③ Pişince tekrar E ile dürümü al.<br>④ Müşteriye dönüp E ile servis et.</p><div class="tips">Depo: sol arka köşe.<br>Geliştirmeler: sağ arka bilgisayar.<br>Reklam: girişteki pano.<br>Her gün 3 dakika, ilk hedef 6 servis.</div><p style="font-size:11px">İlham: <a href="https://www.durumle.com/lezzetler" target="_blank" rel="noopener">Dürümle</a>, <a href="https://www.goodpizzagreatpizza.com/" target="_blank" rel="noopener">Good Pizza, Great Pizza</a>, <a href="https://nordcurrent.com/games/cooking-fever/" target="_blank" rel="noopener">Cooking Fever</a>.</p>${button('Oyuna dön','resume')}`)}save();updateHUD()});
$('#dialog').addEventListener('cancel',e=>{e.preventDefault();if(started){for(let p of staff)if(p.brain.runtime.state==='caught')p.brain.resolve('warn',account);paused=false;closeModal()}});
function togglePause(){if(!started)return;if(paused){paused=false;closeModal();return}if($('#dialog').open)return;paused=true;modal('<div class="eyebrow">KISA BİR MOLA</div><h2>Çayın soğumasın.</h2><p>Oyun duraklatıldı. Şuben seni bekliyor.</p>'+button('Devam et →','resume')+button('Nasıl oynanır?','guide',false,true))}
$('#pause').onclick=togglePause;$('#sound').onclick=()=>{sound=!sound;$('#sound').style.background=sound?'#db973e':'#274b40';$('#sound').setAttribute('aria-label',sound?'Sesi kapat':'Sesi aç');tone()};$('#action').onclick=()=>interact();
addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='escape'){if(!$('#dialog').open)togglePause();return}if($('#dialog').open)return;keys[k]=true;if(k==='e'&&!e.repeat)interact()});addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);addEventListener('blur',()=>{keys={};joy={x:0,y:0}});document.addEventListener('visibilitychange',()=>{keys={};joy={x:0,y:0};last=performance.now()});
const stick=$('#joystick');let joystickPointer=null;
function clearInput(){keys={};joy={x:0,y:0};target=null;autointeract=null;joystickPointer=null;$('#knob').style.transform=''}
function stickMove(e){let v=joystickVector(e.clientX,e.clientY,stick.getBoundingClientRect());joy={x:v.x,y:v.y};$('#knob').style.transform='translate('+v.knobX+'px,'+v.knobY+'px)';target=null;autointeract=null}
stick.addEventListener('pointerdown',e=>{if(joystickPointer!==null||!started||paused||$('#dialog').open)return;e.preventDefault();joystickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);stickMove(e)});
stick.addEventListener('pointermove',e=>{if(e.pointerId===joystickPointer){e.preventDefault();stickMove(e)}});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])stick.addEventListener(ev,e=>{if(e.pointerId===joystickPointer)clearInput()});
addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{clearInput();if(document.hidden&&started)save()});
function touchMode(){return typeof matchMedia==='function'&&matchMedia('(pointer: coarse)').matches}
function liveSheetOpen(){return !$('#kitchen-panel').hidden||!$('#register-panel').hidden}
function syncSheet(){if(document.body){if(liveSheetOpen())document.body.classList.add('sheet-open');else document.body.classList.remove('sheet-open')}}
canvas.addEventListener('pointerdown',e=>{if(!started||paused||$('#dialog').open||liveSheetOpen())return;e.preventDefault();let x=(e.clientX-W/2)/zoom+cam.x,y=(e.clientY-viewportLayout(W,H,touchMode()).anchorY)/zoom+cam.y;let hit=candidates().map(t=>({...t,d:Math.hypot(t.x-x,t.y-y)})).filter(t=>t.d<85).sort((a,b)=>a.d-b.d)[0];if(hit){target=findPath(player.x,player.y,hit.tx,hit.ty);autointeract=hit}else{target=findPath(player.x,player.y,x,y);autointeract=null}if(!target.length&&hit&&Math.hypot(player.x-hit.tx,player.y-hit.ty)<88)interact(hit);else if(!target.length)toast('Açık bir zemine dokun.');else particles.push({type:'target',x:hit?.tx??x,y:hit?.ty??y,life:1.2,max:1.2})});
function floater(x,y,text,color){particles.push({type:'text',x,y,text,color,life:1.8,max:1.8})}function burst(x,y){for(let i=0;i<13;i++)particles.push({type:'confetti',x,y,vx:(Math.random()-.5)*110,vy:-Math.random()*110-20,color:['#f4c961','#e86b51','#9fca7c'][i%3],life:1.2,max:1.2})}
function updateHUD(){$('#cash').textContent=fmt(account.cash);$('#day').textContent=account.day+'. gün';$('#time').textContent=String(Math.floor(Math.max(0,time)/60)).padStart(2,'0')+':'+String(Math.floor(Math.max(0,time)%60)).padStart(2,'0');$('#score').textContent=combo.fever>0?'FEVER '+Math.ceil(combo.fever)+'s':served+' / '+dayPlan(account.day).target;$('#held').hidden=carrying===null;$('#held').textContent=carrying!==null?'🌯 Elinde: '+MENU[carrying].name:'';let mission='Müşterileri karşıla',hint='? işaretli müşteriye yaklaş.';if(carrying!==null){mission='Sıcakken servis et';hint=MENU[carrying].name+' isteyen müşteriye götür.'}else if(jobs.length){mission=jobs.some(j=>j.burnt)?'Izgarada yanık var!':jobs.some(j=>j.remaining<=0)?'Dürümler hazır!':'Üç göz birden çalışsın';hint='Tezgâha yaklaş: '+jobs.length+'/3 göz dolu.'}else if(customers.some(c=>c.state==='ordered')){mission='Şimdi mutfağa!';hint='Arkadaki ızgaraya git, siparişi hazırla.'}else if(served>0){mission='Mahallenin favorisi ol';hint='Masaları gez, yeni siparişleri al.'}$('#mission').textContent=mission;$('#hint').textContent=hint;nearest=getNear();let context=nearest?.label??'Zemine dokun veya yürüyerek yaklaş';if(nearest?.id==='grill')context='Izgara · '+jobs.length+'/3 göz dolu';$('#context').textContent=context;$('#action').disabled=!nearest||!started||!!playerWork;updateServiceHUD();}
function update(dt){elapsed+=dt;if(!started||paused||$('#dialog').open||document.hidden)return;staffUpdate(dt);saveElapsed+=dt;if(saveElapsed>=2){saveElapsed=0;save()}time-=dt;if(time<=0){endDay();return}let dx=(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,dy=(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y,len=Math.hypot(dx,dy);if(len>.05){target=null;autointeract=null;move(player,dx/Math.max(1,len)*(190+account.speed*35)*dt,dy/Math.max(1,len)*(190+account.speed*35)*dt)}else if(target?.length){follow(player,target,190+account.speed*35,dt);if(!target.length&&autointeract){let t=autointeract;autointeract=null;if(Math.hypot(player.x-t.tx,player.y-t.ty)<90)interact(t)}}spawnIn-=dt;if(spawnIn<=0){addCustomer();spawnIn=Math.max(3,180/dayPlan(account.day).customers)*(account.ad?.75:1)*(isRush()?.48:1)}for(let c of customers){if(c.state==='queue'){c.patience-=dt;if(c.patience<=0){c.state='gone';missed++;combo.fail()}}else if(c.state==='checkoutWalk'){follow(c,c.path,105,dt);if(!c.path.length)c.state='checkout'}else if(c.state==='checkout'){c.payPatience-=dt;if(c.payPatience<=0){missed++;leave(c);toast('Kasada bekleyen müşteri ödeme yapmadan gitti.')}}else if(c.state==='walking'){follow(c,c.path,90,dt);if(!c.path.length)c.state='waiting'}else if(c.state==='leaving'){follow(c,c.path,100,dt)}else if(c.state==='eating'){c.eat-=dt;if(c.eat<=0)queueCheckout(c)}else{c.patience-=dt;if(c.patience<=0){leave(c);missed++;combo.fail();floater(c.x,c.y-55,'Çok bekledim…','#efb0a1')}}}customers=customers.filter(c=>c.state!=='gone'&&!(c.state==='leaving'&&!c.path.length));seatQueue();updateCooking(dt);updateService(dt);hudClock+=dt;if(hudClock>.12){hudClock=0;updateHUD()}}
function restoreSession(){let v=account.session;if(!v){morning();return}closeModal();started=true;paused=false;time=v.time;served=v.served;missed=v.missed;revenue=v.revenue;spawnIn=v.spawnIn;spawned=v.spawned;customers=v.customers;jobs=v.jobs??(v.job?[{...v.job,id:(v.orderId??0)+1,slot:0,age:0,burnt:false}]:[]);cleanPlates=v.cleanPlates??8;sinkDirty=v.sinkDirty??0;tableDishes=v.tableDishes??{};paid=v.paid??v.served;burned=v.burned??0;fastServes=v.fastServes??0;cleanedTables=v.cleanedTables??0;carrying=v.carrying;orderId=v.orderId;Object.assign(player,v.player);dirty=new Set(v.dirty);dayCosts=v.dayCosts;dailyTips=v.dailyTips;catches=new Set(v.catches);Object.assign(combo,v.combo);for(let p of staff){let saved=v.staff.find(q=>q.id===p.brain.id);if(saved){p.x=saved.x;p.y=saved.y;p.carried=saved.carried}p.task=null;p.path=[];if(p.brain.runtime.state==='caught')p.brain.resolve('warn',account)}updateHUD();toast('Vardiya kaldığın yerden devam ediyor.')}
function morning(){
 const plan=dayPlan(account.day),live=staff.filter(p=>p.brain.runtime.state!=='fired');
 modal(`<div class="eyebrow">SABAH HAZIRLIĞI · ${account.day}. GÜN</div><h2>Bugünün planı.</h2><p>${plan.customers} müşteri hedefi · ${plan.tables} masa · Günlük hedef ${plan.target} servis.<br>${plan.mechanic}</p><div class="tips">Kasa ${fmt(account.cash)} · Stok ${account.stock} porsiyon<br>Görev: ${plan.quest}<br>Uzun vade: ${fmt(account.earned)} / ₺10.000 · ${account.xp} XP</div><h3>Bugünün menüsü</h3>${MENU.map((r,i)=>button((account.menu.includes(i)?'✓ ':'○ ')+r.name,'menu-'+i,false,true)).join('')}<h3>Vardiya</h3>${live.map(p=>button(p.brain.name+' · '+CONFIG.staff.roles[p.brain.role].label+'<small>'+({full:'Tüm gün',morning:'Öğle',evening:'Akşam',off:'İzinli'}[p.brain.runtime.shift])+' · '+fmt(p.brain.contract.wage)+' / tam gün · Değiştirmek için dokun</small>','shift-'+p.brain.id,false,true)).join('')}${button('Personel işe al','hire',false,true)}${button('Stok al · +12 porsiyon / ₺240','morning-stock',account.cash<240||account.stock+12>48+account.fridge*24,true)}${account.cash<240&&account.stock<3?button('Tedarik desteği · +6 porsiyon','morning-rescue',false,true):''}${button('Yatırım ağacı','tree',false,true)}${button('Kapıları aç →','start')}`)
}
function upgradeTree(){modal('<div class="eyebrow">MUTFAK · SALON · PERSONEL</div><h2>Yatırım ağacı</h2><p>Kasa '+fmt(account.cash)+'</p>'+CONFIG.upgrades.map(u=>{const level=account[u.id]??0,cost=u.baseCost+level*u.costStep;return button(u.name+' · '+fmt(cost)+'<small>'+u.branch+' · Seviye '+level+'/'+u.maxLevel+' · Gün '+u.unlockDay+'</small>','upgrade-'+u.id,account.day<u.unlockDay||level>=u.maxLevel||account.cash<cost)}).join('')+button(started?'Dükkâna dön':'Sabah hazırlığı',started?'close':'morning',false,true))}
function catchStaff(p){if(!p.brain.catch({distance:Math.hypot(player.x-p.x,player.y-p.y)}))return;catches.add(p.brain.id);shake=9;burst(p.x,p.y-60);tone(250);showCatch(p)}
function showCatch(p){const b=p.brain,r=b.runtime;modal(`<div class="eyebrow">SUÇÜSTÜ!</div><h2>${b.name}, işler bekliyor.</h2><p>${CONFIG.staff.slacking.behaviors.find(x=>x.id===r.slackBehavior)?.label??'Kaytarıyor'}.<br>Disiplin ${Math.round(b.stats.discipline)} · Moral ${Math.round(r.morale)} · Yorgunluk ${Math.round(r.fatigue)}<br>Bugüne kadar ${r.caughtCount} kez yakalandı.</p>${button('Uyar<small>Disiplin +7 · Moral −12</small>','warn-'+b.id)}${button('Kahve ver · ₺30<small>Moral +15 · 7 saniye izinli mola</small>','coffee-'+b.id,account.cash<30)}${button('İşten çıkar<small>En az 3 suçüstü gerekir</small>','fire-'+b.id,r.caughtCount<3,true)}`)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const a=b.dataset.do;
 if(a==='hire')hiring();if(a==='tree')upgradeTree();
 if(a.startsWith('menu-')){let i=Number(a.slice(5));if(account.menu.includes(i)){if(account.menu.length>1)account.menu=account.menu.filter(v=>v!==i);else toast('Menüde en az bir dürüm olmalı.')}else account.menu.push(i);morning()}
 if(a.startsWith('shift-')){let p=staff.find(p=>p.brain.id===a.slice(6));if(p){let shifts=['full','morning','evening','off'];p.brain.runtime.shift=shifts[(shifts.indexOf(p.brain.runtime.shift)+1)%4];morning()}}
 if(a.startsWith('hire-')){if(hireEmployee(a.slice(5))){tone(700);hiring()}}
 if(a==='morning-stock'&&account.cash>=240&&account.stock+12<=48+account.fridge*24){account.cash-=240;account.stock+=12;morning()}
 if(a==='morning-rescue'&&account.cash<240&&account.stock<3){account.stock+=6;morning()}
 if(a.startsWith('upgrade-')){let u=CONFIG.upgrades.find(u=>u.id===a.slice(8));if(u){let lvl=account[u.id]??0,cost=u.baseCost+lvl*u.costStep;if(account.day>=u.unlockDay&&lvl<u.maxLevel&&account.cash>=cost){account.cash-=cost;account[u.id]=lvl+1;tone(800);upgradeTree()}}}
 for(const choice of ['warn','coffee','fire'])if(a.startsWith(choice+'-')){const p=staff.find(p=>p.brain.id===a.slice(choice.length+1));if(p){let result=p.brain.resolve(choice,account);if(result.ok){if(choice==='coffee')dayCosts.coffee+=result.cost;p.task=null;p.path=[];closeModal();toast(choice==='warn'?'Uyarıldı. Disiplini arttı, morali düştü.':choice==='coffee'?'Kahve molası. Biraz nefes alsın.':'İş sözleşmesi sona erdi.')}}}
 save();updateHUD();
});
function chooseStaffTask(p){const role=p.brain.role;
 if(role==='manager'){const q=staff.find(q=>q!==p&&q.brain.runtime.state==='slacking');return q?{id:'supervise-'+q.brain.id,type:'supervise',target:q,x:q.x,y:q.y}:null}
 if(role==='cashier'){let c=customers.find(c=>c.state==='checkout'&&!tasks.tasks.get('pay-'+c.id)?.owner);if(c)return {id:'pay-'+c.id,type:'checkout',c,x:650,y:680}}
 if(role==='dishwasher'){if(sinkDirty&&cleanPlates<5)return {id:'wash',type:'wash',x:720,y:320};let id=[...dirty].find(id=>!tasks.tasks.get('clean-'+id)?.owner);if(id!==undefined){let t=tables[id];return {id:'clean-'+id,type:'clean',table:id,x:t.x+(t.x<550?96:-96),y:t.y+12}}if(sinkDirty)return {id:'wash',type:'wash',x:720,y:320}}
 if(role==='prep'&&prepBoost<2&&account.stock>0)return {id:'prep',type:'prep',x:670,y:320};
 if(role==='host'){let c=customers.find(c=>['waiting','ordered'].includes(c.state)&&!c.greeted);if(c)return {id:'greet-'+c.id,type:'greet',c,x:c.x,y:c.y}}
 if(role==='cook'){let burnt=jobs.find(j=>j.burnt);if(burnt)return {id:'burn-'+burnt.id,type:'burn',jobId:burnt.id,x:480,y:320};if(jobs.length<3&&account.stock>0){let c=customers.find(c=>c.state==='ordered'&&neededPortions(c.recipe)>0&&!tasks.tasks.get('cook-'+c.id)?.owner);if(c)return {id:'cook-'+c.id,type:'cook',c,x:480,y:320}}}
 if(role==='waiter'){
  if(p.carried!==null){let c=customers.find(c=>c.state==='ordered'&&c.recipe===p.carried&&!tasks.tasks.get('serve-'+c.id)?.owner);if(c)return {id:'serve-'+c.id,type:'serve',c,x:c.x,y:c.y};if(!customers.some(c=>c.state==='ordered'&&c.recipe===p.carried)){p.carried=null;dayCosts.waste+=20;dayCosts.food=Math.max(0,dayCosts.food-20);combo.fail()}}
  if(p.carried===null){let j=jobs.find(j=>j.remaining<=0&&!j.burnt&&!tasks.tasks.get('collect-'+j.id)?.owner);if(j)return {id:'collect-'+j.id,type:'collect',jobId:j.id,x:480,y:320};let c=customers.find(c=>c.state==='waiting'&&!tasks.tasks.get('order-'+c.id)?.owner);if(c)return {id:'order-'+c.id,type:'order',c,x:c.x,y:c.y}}
 }return null}
function neededPortions(recipe){return customers.filter(c=>c.state==='ordered'&&c.recipe===recipe).length-jobs.filter(j=>j.recipe===recipe&&!j.burnt).length-staff.filter(p=>p.carried===recipe).length-(carrying===recipe?1:0)}

function staffUpdate(dt){combo.tick(dt);let evening=time<90;for(let p of staff){let brain=p.brain,r=brain.runtime;const offShift=r.shift==='off'||r.shift==='morning'&&evening||r.shift==='evening'&&!evening;let gossip=staff.some(q=>q!==p&&q.brain.traits.includes('gossip')&&q.brain.available&&Math.hypot(q.x-p.x,q.y-p.y)<100);brain.tick(dt,{hasWork:!!p.task,offShift,evening,gossip,security:account.camera>0,coffeeLevel:account.coffee,atWork:Math.hypot(p.x-650,p.y-680)<30,fever:combo.fever>0});
 if(r.state==='fired'||r.state==='caught')continue;
 if(['slacking','returning','break'].includes(r.state)||offShift){let zone=CONFIG.staff.slacking.behaviors.find(b=>b.id===r.slackBehavior)?.zone;let dest=r.state==='slacking'&&zone==='stock'?{x:185,y:330}:{x:650,y:680};if(!p.path.length&&Math.hypot(p.x-dest.x,p.y-dest.y)>25)p.path=findPath(p.x,p.y,dest.x,dest.y);follow(p,p.path,100,dt);p.task=null;tasks.release(brain.id);continue}
 if(!p.task){let task=chooseStaffTask(p);if(task){tasks.upsert(task);if(tasks.claim(task.id,brain.id)){p.task=task;p.path=findPath(p.x,p.y,task.x,task.y);p.timer=0}}}
 if(!p.task)continue;let task=p.task;if(task.c&&!['waiting','ordered','checkout'].includes(task.c.state)){tasks.complete(task.id,brain.id);p.task=null;continue}
 if(Math.hypot(p.x-task.x,p.y-task.y)>45){follow(p,p.path,155*brain.speedMultiplier({evening,gossip,fever:combo.fever>0}),dt);if(!p.path.length&&Math.hypot(p.x-task.x,p.y-task.y)>40){tasks.release(brain.id);p.task=null}continue}
 p.timer+=dt*brain.speedMultiplier({evening,gossip,fever:combo.fever>0});if(p.timer<(task.type==='wash'?3:task.type==='clean'?1.5:task.type==='checkout'?3:.7))continue;
 if(task.type==='order'&&task.c.state==='waiting'){task.c.state='ordered';floater(p.x,p.y-80,'Sipariş!','#f9e9b8')}
 if(task.type==='collect')takeCooked(task.jobId,p);
 if(task.type==='serve'&&p.carried===task.c.recipe){if(brain.traits.includes('clumsy')&&Math.random()<.05){dayCosts.waste+=20;dayCosts.food=Math.max(0,dayCosts.food-20);combo.fail();floater(p.x,p.y-60,'Eyvah!','#f0aa8a');shake=5;p.carried=null}else if(deliver(task.c,p))p.carried=null}
 if(task.type==='cook')startCooking(task.c.recipe);
 if(task.type==='burn')discardBurnt(task.jobId);
 if(task.type==='wash')washBatch();
 if(task.type==='checkout'&&task.c.state==='checkout')settleBill(task.c);
 if(task.type==='prep')prepBoost=Math.min(2,prepBoost+1);
 if(task.type==='clean')cleanTable(task.table);
 if(task.type==='greet'&&!task.c.greeted){task.c.greeted=true;task.c.patience+=12;task.c.full+=12}
 if(task.type==='supervise'&&task.target.brain.catch({distance:Math.hypot(p.x-task.target.x,p.y-task.target.y),manager:true})){task.target.brain.resolve('warn',account);floater(p.x,p.y-75,'İş başına!','#ffdeac')}
 tasks.complete(task.id,brain.id);p.task=null;p.path=[];
 }
 if(account.dishwasher&&sinkDirty){cleanClock+=dt;if(cleanClock>=6){cleanClock=0;washBatch()}}
}

function isRush(){const t=180-time;return t>=35&&t<70||t>=105&&t<140}
function activeDining(c){return ['walking','waiting','ordered','eating'].includes(c.state)}
function seatCustomer(c,t){c.table=t.id;const side=t.x<550?1:-1;c.tx=t.x+side*96;c.ty=t.y+12;c.path=findPath(c.x,c.y,c.tx,c.ty);c.state='walking';c.patience=c.full}
function seatQueue(){for(let c of customers.filter(c=>c.state==='queue')){let t=tables.slice(0,dayPlan(account.day).tables).find(t=>!dirty.has(t.id)&&!customers.some(q=>q.table===t.id&&activeDining(q)));if(!t)break;seatCustomer(c,t)}}
function addCustomer(){let plan=dayPlan(account.day);if(spawned>=plan.customers)return;spawned++;let roll=Math.random(),mix=plan.mix,type=roll<mix[2]?CONFIG.customers[2]:roll<mix[2]+mix[1]?CONFIG.customers[1]:CONFIG.customers[0];let id=++orderId,c={type,id,table:null,x:550,y:785,tx:550,ty:785,path:[],state:'queue',recipe:account.menu[Math.floor(Math.random()*account.menu.length)],patience:45,full:(type.patience+account.deco*12)*(account.jukebox?1.12:1),shirt:['#709ba4','#e4ac55','#9d80a9','#78975e'][id%4],skin:['#e8b88e','#c98f68','#edc9a3'][id%3],hair:['#513b2e','#3a302b','#925d39'][id%3],dir:1,walk:0,eat:0,staffCard:id%5===0,payment:id%3===0?'card':'cash'};customers.push(c);seatQueue();let q=customers.filter(c=>c.state==='queue');q.forEach((c,i)=>{c.x=495+(i%4)*27;c.y=780-Math.floor(i/4)*24});}
function dirtyTable(c){if(c.table===null||dirty.has(c.table))return;dirty.add(c.table);tableDishes[c.table]=c.plates??1}
function beginCleaning(id){if(playerWork||!dirty.has(id))return;playerWork={type:'clean',id,remaining:1.3,full:1.3,x:player.x,y:player.y};toast('Tabaklar toplanıyor…')}
function cleanTable(id){if(!dirty.delete(id))return false;sinkDirty+=tableDishes[id]??1;delete tableDishes[id];cleanedTables++;const t=tables[id];floater(t.x,t.y-50,'Lavaboya götürüldü','#edf7c1');account.xp+=3;tone(550);seatQueue();return true}
function beginWashing(){if(playerWork||sinkDirty===0){toast('Lavaboda kirli tabak yok. Önce masaları topla.');return}playerWork={type:'wash',remaining:2.7,full:2.7,x:player.x,y:player.y};toast('Bulaşıklar yıkanıyor…')}
function washBatch(){let n=Math.min(3,sinkDirty);if(!n)return false;sinkDirty-=n;cleanPlates+=n;tone(650);floater(720,240,'+'+n+' temiz tabak','#d9f1b5');return true}
function deliver(c,server){if(c.state!=='ordered')return false;const m=c.type??CONFIG.customers[0],plates=m.id==='family'?2:1;if(cleanPlates<plates){if(server===player)toast('Temiz tabak kalmadı! Lavaboda bulaşık yıka.');return false}if(m.id==='family'&&account.stock<1){toast('Aile için ek porsiyon stoğu gerekli.');return false}if(m.id==='family'){account.stock--;dayCosts.food+=20}cleanPlates-=plates;c.plates=plates;served++;c.state='eating';c.eat=m.eatSeconds;let fast=c.patience/c.full>=.55;if(fast)fastServes++;let tip=Math.round(c.patience/c.full*20*(m.id==='rushed'&&!fast?1:m.tipMultiplier)*(1+account.lighting*.15)*(combo.fever>0?2:1));c.bill={subtotal:Math.round(MENU[c.recipe].price*m.billMultiplier),tip,eligibleDiscount:c.staffCard===true,settled:false};let amount=billTotal(c);let tender=amount<=100?100:amount<=200?200:Math.ceil(amount/100)*100;c.bill.notes=tender===100?[50,50]:tender===200?[100,50,50]:Array.from({length:tender/100},()=>100);const fever=combo.delivered({quality:server.brain?.stats.skill>=0?.8+server.brain.stats.skill/500:1,patienceRatio:c.patience/c.full});toast(fever?'FEVER! Ekip +%25 hız, bahşiş ×2!':'Afiyet olsun! Müşteri yemekten sonra kasaya gelecek.');if(fever)shake=4;floater(c.x,c.y-65,'Afiyet olsun!','#fff0a1');burst(c.x,c.y-30);tone(700);save();return true}
function billTotal(c){return c.bill.subtotal-Math.round(c.bill.subtotal*(c.bill.eligibleDiscount?.2:0))+c.bill.tip}
function queueCheckout(c){dirtyTable(c);if(!c.bill){leave(c);return}c.state='checkoutWalk';c.payPatience=65;c.path=findPath(c.x,c.y,615,655);toast('Masa '+(c.table+1)+' kasaya geliyor. Tabaklar masada kaldı.')}
function management(){modal('<div class="eyebrow">ŞUBE MÜDÜRÜ</div><h2>Ekip ve işletme</h2>'+button('Personel al / ekibi gör','hire')+button('Ekipman ve dekorasyon','tree',false,true)+button('Dükkâna dön','close',false,true))}
function hireCost(role){return role==='waiter'&&!account.freeWaiterUsed?0:CONFIG.staff.roles[role].hireCost}
function hireEmployee(role){let def=CONFIG.staff.roles[role];if(!def||account.day<def.unlockDay||account.cash<hireCost(role)||staff.filter(p=>p.brain.runtime.state!=='fired').length>=6)return false;account.cash-=hireCost(role);if(role==='waiter')account.freeWaiterUsed=true;let n=staff.length;staff.push(makeStaff({id:'staff-'+Date.now()+'-'+n,name:STAFF_NAMES[n%STAFF_NAMES.length],role,traits:[['clumsy','gossip','nightOwl'][n%3]],stats:{speed:65,skill:70,stamina:65,discipline:48},contract:{wage:def.wage,hiredDay:account.day}}));save();return true}
function hiring(){let live=staff.filter(p=>p.brain.runtime.state!=='fired');modal('<div class="eyebrow">EKİBİNİ KUR</div><h2>Personel · '+live.length+'/6</h2><p>İlk garson ücretsiz. Aşçı, garson, bulaşıkçı ve kasiyer ilk günden alınabilir. Maaş gün sonunda ödenir.</p>'+live.map(p=>'<div class="roster"><b>'+p.brain.name+' · '+CONFIG.staff.roles[p.brain.role].label+'</b><small>'+({slacking:'Kaytarıyor',working:'Çalışıyor',idle:'Görev bekliyor',break:'İzinli mola',caught:'Uyarı bekliyor',returning:'İşe dönüyor'}[p.brain.runtime.state]??p.brain.runtime.state)+' · Moral '+Math.round(p.brain.runtime.morale)+' · Yorgunluk '+Math.round(p.brain.runtime.fatigue)+'</small></div>').join('')+Object.entries(CONFIG.staff.roles).map(([id,r])=>button(r.label+' · '+(hireCost(id)===0?'ÜCRETSİZ':fmt(hireCost(id)))+'<small>'+fmt(r.wage)+' / gün'+(r.unlockDay>account.day?' · '+r.unlockDay+'. günde açılır':' · Şimdi işe al')+'</small>','hire-'+id,account.day<r.unlockDay||account.cash<hireCost(id)||live.length>=6)).join('')+button(started?'Dükkâna dön':'Hazırlığa dön',started?'close':'morning',false,true))}
function openRegister(){let c=customers.find(c=>c.state==='checkout'&&!c.bill?.settled);if(!c){toast('Kasada ödeme bekleyen müşteri yok.');return}clearInput();$('#kitchen-panel').hidden=true;register=c;registerCounted=[];changeGiven=[];discountApplied=false;$('#register-panel').hidden=false;renderRegister();syncSheet()}
function renderRegister(){if($('#register-panel').hidden||!register)return;let key=JSON.stringify([register.id,registerCounted,changeGiven,discountApplied]);if(renderRegister.lastKey===key){$('#register-clock').textContent=Math.ceil(register.payPatience)+' sn';return}renderRegister.lastKey=key;let c=register,b=c.bill,subtotal=b.subtotal,discount=discountApplied?Math.round(subtotal*.2):0,due=subtotal-discount+b.tip,tender=registerCounted.reduce((n,i)=>n+b.notes[i],0),change=changeGiven.reduce((n,x)=>n+x,0);$('#register-body').innerHTML='<div class="live-title"><b>DÜRÜMLE KASA / POS</b><span id="register-clock">'+Math.ceil(c.payPatience)+' sn</span><button data-do="register-close" aria-label="Kasayı kapat">×</button></div><div class="receipt"><b>'+MENU[c.recipe].name+(c.type.id==='family'?' × 2':'')+'</b><span>'+fmt(subtotal)+'</span><small>Personel indirimi '+(discountApplied?'%20':'uygulanmadı')+'</small><span>−'+fmt(discount)+'</span><small>Gönüllü bahşiş</small><span>'+fmt(b.tip)+'</span><b>ÖDENECEK</b><strong>'+fmt(due)+'</strong></div><div class="card-status">'+(b.eligibleDiscount?'✓ Geçerli personel kartı doğrulandı.':'Personel kartı yok — indirim uygulanamaz.')+'</div>'+button(discountApplied?'Personel indirimi uygulandı':'%20 personel indirimi uygula','discount',!b.eligibleDiscount||discountApplied)+(c.payment==='card'?'<p>Ödeme türü: Kart</p>'+button('POS · '+fmt(due)+' tahsil et','pay-card'):'<p>Ödeme türü: Nakit. Her banknota dokunarak say.</p><div class="notes">'+b.notes.map((v,i)=>button((registerCounted.includes(i)?'✓ ':'')+fmt(v),'count-note-'+i,registerCounted.includes(i))).join('')+'</div><div class="cash-totals">Sayılan: <b>'+fmt(tender)+'</b> · Verilen para üstü: <b>'+fmt(change)+'</b></div><p>Para üstünü hazırla:</p><div class="denoms">'+[200,100,50,20,10,5,2,1].map(v=>button(fmt(v),'change-'+v)).join('')+'</div>'+button('Son banknotu/bozukluğu geri al','change-undo',!changeGiven.length,true)+button('Para üstünü ver ve hesabı kapat','pay-cash',registerCounted.length!==b.notes.length))+button('İşlemi kapat (tahsilat yapılmaz)','register-close',false,true)}
function settleBill(c){if(c.state!=='checkout'||!c.bill||c.bill.settled)return false;const due=billTotal(c);c.bill.settled=true;const sales=due-c.bill.tip;account.cash+=due;account.earned+=due;account.total++;revenue+=due;dailyTips+=c.bill.tip;paid++;floater(650,620,'+'+fmt(due),'#ffe292');burst(650,660);tone(1000);leave(c);save();return true}
function submitPayment(kind){let c=register;if(!c||c.state!=='checkout'||c.bill.settled)return false;if(c.bill.eligibleDiscount&&!discountApplied){toast('Geçerli personel kartı var. Önce %20 indirimi uygula.');return false}if(kind!==c.payment){toast('Müşterinin seçtiği ödeme türünü kullan.');return false}if(kind==='cash'){if(registerCounted.length!==c.bill.notes.length)return false;const given=c.bill.notes.reduce((a,b)=>a+b,0),change=changeGiven.reduce((a,b)=>a+b,0);if(change!==given-billTotal(c)){toast(change<given-billTotal(c)?'Para üstü eksik. Tekrar say.':'Para üstü fazla. Son banknotu geri al.');shake=3;return false}}if(!settleBill(c))return false;$('#register-panel').hidden=true;register=null;toast('Tahsilat tamamlandı. Sıradaki müşteri!');return true}
function updateService(dt){if(playerWork){if(Math.hypot(player.x-playerWork.x,player.y-playerWork.y)>28){playerWork=null;toast('İşlem yarıda kaldı.')}else{playerWork.remaining-=dt;if(playerWork.remaining<=0){if(playerWork.type==='wash')washBatch();else cleanTable(playerWork.id);playerWork=null}}}if(!$('#kitchen-panel').hidden&&Math.hypot(player.x-480,player.y-320)>145)$('#kitchen-panel').hidden=true;if(register&&(register.state!=='checkout'||Math.hypot(player.x-650,player.y-680)>140)){$('#register-panel').hidden=true;register=null}}
function updateServiceHUD(){let queue=customers.filter(c=>c.state==='queue').length,payQueue=customers.filter(c=>['checkout','checkoutWalk'].includes(c.state)).length,slackers=staff.filter(p=>p.brain.runtime.state==='slacking').length;$('#service-status').innerHTML='<b class="'+(isRush()?'rush':'')+'">'+(isRush()?'YOĞUN SAAT!':'SERVİS · MOBİL')+'</b><span>Izgara '+jobs.length+'/3</span><span>Tabak '+cleanPlates+' temiz / '+sinkDirty+' kirli</span><span>Masa '+dirty.size+' kirli</span><span>Kasa kuyruğu '+payQueue+'</span><span>Kapıda '+queue+'</span><span>Ekip '+staff.filter(p=>p.brain.runtime.state!=='fired').length+(slackers?' · '+slackers+' kaytarıyor':'')+'</span>';$('#score').textContent=combo.fever>0?'FEVER '+Math.ceil(combo.fever)+'s':paid+' / '+dayPlan(account.day).target;if(playerWork){$('#context').textContent=(playerWork.type==='wash'?'Yıkanıyor':'Toplanıyor')+'… '+Math.ceil(playerWork.remaining)+' sn'}if(cleanPlates===0){$('#mission').textContent='Temiz tabak bitti!';$('#hint').textContent='Kirli masaları topla ve lavaboda yıka.'}else if(payQueue){$('#mission').textContent='Kasada müşteri bekliyor';$('#hint').textContent='Girişteki POS’a git, hesabı kapat.'}renderKitchen();renderRegister();syncSheet()}
function drawServiceWorld(){// Dishwasher beside kitchen, cash register by entrance.
rr(686,188,79,57,7,'#91aaa7','#536b69');rr(695,196,61,38,9,'#627c7b');line(720,187,720,170,'#c6d4c8',5);line(720,170,735,170,'#c6d4c8',5);text('LAVABO',725,258,9,'#f9edce');for(let i=0;i<Math.min(sinkDirty,6);i++)ellipse(700,202-i*4,14,6,'#e5e0d0');text(cleanPlates+' TEMİZ / '+sinkDirty+' KİRLİ',725,286,8,'#536849');box(600,715,103,45,35,'#bb956b','#885f40');rr(636,655,47,32,5,'#304a41');rr(641,660,37,20,2,'#a7c9ac');text('KASA',660,671,8,'#355b41');line(656,687,656,700,'#4c6655',5);rr(610,690,27,15,3,'#3c5148');text('ÖDEME',651,733,10,'#f5dfb2');for(let c of customers){if(c.state==='queue')bubble(c.x,c.y-85,'Sıra…','#ffedbe',true);if(['checkout','checkoutWalk'].includes(c.state))bubble(c.x,c.y-87,c.payment==='card'?'KART':'NAKİT','#d6eac2',true)}if(playerWork){rr(player.x-23,player.y-85,46,6,3,'#8b805f');rr(player.x-23,player.y-85,46*(1-playerWork.remaining/playerWork.full),6,3,'#bfdb7a')}}
$('#team').onclick=()=>hiring();
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const a=b.dataset.do;if(a==='register-close'){$('#register-panel').hidden=true;register=null}if(a==='discount'&&register?.bill.eligibleDiscount)discountApplied=true;if(a.startsWith('count-note-')&&register){let i=Number(a.slice(11));if(i>=0&&i<register.bill.notes.length&&!registerCounted.includes(i))registerCounted.push(i)}if(a.startsWith('change-')&&a!=='change-undo'){let v=Number(a.slice(7));if([200,100,50,20,10,5,2,1].includes(v))changeGiven.push(v)}if(a==='change-undo')changeGiven.pop();if(a==='pay-cash')submitPayment('cash');if(a==='pay-card')submitPayment('card');renderRegister();updateHUD()});

// Everything below is original canvas artwork: the restaurant, furniture, characters and effects.
function rr(x,y,w,h,r,fill,stroke){g.beginPath();g.roundRect(x,y,w,h,r);if(fill){g.fillStyle=fill;g.fill()}if(stroke){g.strokeStyle=stroke;g.lineWidth=2;g.stroke()}}
function ellipse(x,y,rx,ry,color){g.beginPath();g.ellipse(x,y,rx,ry,0,0,Math.PI*2);g.fillStyle=color;g.fill()}
function line(x,y,x2,y2,color,width=2){g.beginPath();g.moveTo(x,y);g.lineTo(x2,y2);g.strokeStyle=color;g.lineWidth=width;g.lineCap='round';g.stroke()}
function text(t,x,y,size=14,color='#42533e',align='center',weight=600){g.fillStyle=color;g.font=`${weight} ${size}px Outfit, sans-serif`;g.textAlign=align;g.textBaseline='middle';g.fillText(t,x,y)}
function box(x,y,w,h,z,top,front,edge='#5d514033'){rr(x,y,w,h,5,front,edge);rr(x,y-z,w,h,5,top,edge);rr(x,y+h-z,w,z,3,front,edge)}
function plant(x,y,size=1){g.save();g.translate(x,y);g.scale(size,size);ellipse(0,7,24,10,'#1d3d3030');box(-17,-7,34,20,22,'#d79e6a','#b8794b');line(0,-10,0,-58,'#426b42',5);for(let i=0;i<6;i++){let a=i*1.1;g.save();g.translate(Math.cos(a)*11,-32-i*4);g.rotate(a);ellipse(0,0,10,23,i%2?'#7ba359':'#56844f');line(0,0,0,-15,'#91b86a',1);g.restore()}g.restore()}
function wrap(x,y,scale=1){g.save();g.translate(x,y);g.scale(scale,scale);g.rotate(-.4);rr(-10,-19,20,39,6,'#ead49e','#bc975b');rr(-10,1,20,19,3,'#f8f1d8');line(-8,8,8,8,'#dc4434',5);for(let i=0;i<5;i++)ellipse(-6+i*3,-16-(i%2)*2,3,4,i%2?'#79a14c':'#b9663b');line(-3,-10,-2,-4,'#d3ad70',2);g.restore()}
function character(p){const moving=p===player?(Math.hypot(joy.x,joy.y)>.05||Object.values(keys).some(Boolean)||target?.length):(p.brain?!!p.path?.length:['walking','leaving'].includes(p.state)),bob=moving?Math.sin(p.walk)*2:Math.sin(elapsed*2+p.x)*.6;g.save();g.translate(p.x,p.y);ellipse(0,5,19,9,'#4f423535');if(p.chef){g.strokeStyle='#fff4af';g.lineWidth=3;g.beginPath();g.ellipse(0,5,23,11,0,0,Math.PI*2);g.stroke()}const step=moving?Math.sin(p.walk)*5:0;rr(-13,-9+step,10,15,4,'#3e4647');rr(3,-9-step,10,15,4,'#3e4647');rr(-14,2+step,12,7,3,'#343637');rr(3,2-step,12,7,3,'#343637');g.translate(0,bob);rr(-19,-43,38,36,11,p.shirt,'#51433233');rr(-24,-37,9,25,5,p.skin);rr(15,-37,9,25,5,p.skin);if(p.chef){rr(-12,-35,24,25,4,'#f9ecce');line(-12,-34,-7,-44,'#f9ecce',4);line(12,-34,7,-44,'#f9ecce',4);text('d',0,-22,15,'#d64334')}ellipse(0,-53,19,22,p.skin);ellipse(-18,-52,4,6,p.skin);ellipse(18,-52,4,6,p.skin);rr(-18,-74,36,17,10,p.hair);if(p.chef){rr(-19,-77,38,9,4,'#e33f32');rr(-18,-82,36,11,5,'#e84b3b');rr(p.dir>0?5:-26,-75,22,5,3,'#c3312a')}const eye=p.dir*3;ellipse(-7+eye,-52,2,2.5,'#493b32');ellipse(7+eye,-52,2,2.5,'#493b32');line(-3+eye,-43,3+eye,-42,'#a16850',1.5);ellipse(-12,-46,4,2,'#dd9b7a99');if(p===player&&carrying!==null){rr(-24,-31,48,8,4,'#a97e55');wrap(0,-35,.65)}g.restore()}
function bubble(x,y,label,color='#fff9e9',small=false){let width=Math.max(small?35:70,label.length*(small?7:7.5)+22);g.save();g.translate(x,y+Math.sin(elapsed*2)*2);rr(-width/2,-25,width,31,10,'#685d4130');rr(-width/2,-29,width,31,10,color,'#ffffff');g.beginPath();g.moveTo(-5,2);g.lineTo(0,9);g.lineTo(7,2);g.fillStyle=color;g.fill();text(label,0,-13,small?13:12,'#604e3b');g.restore()}
function table(t){const x=t.x,y=t.y;ellipse(x,y+18,78,42,'#80613d20');for(const side of [-1,1]){box(x+side*90-20,y-8,40,37,16,'#b6563d','#8d4432');rr(x+side*90-20,y+8,40,9,4,'#dd825a');line(x+side*90-14,y+25,x+side*90-14,y+37,'#704c35',4);line(x+side*90+14,y+25,x+side*90+14,y+37,'#704c35',4)}line(x-42,y+18,x-42,y+39,'#885734',7);line(x+42,y+18,x+42,y+39,'#885734',7);box(x-62,y-36,124,72,25,'#d9aa70','#aa7447');line(x-52,y-45,x+52,y-45,'#ebc28e',2);line(x-52,y-21,x+52,y-21,'#ba875450',1);rr(x-9,y-43,18,13,3,'#fff1d6');text('d',x,y-36,12,'#d84f3c');rr(x+31,y-49,9,19,3,'#d64635');rr(x+30,y-51,11,5,2,'#f0d1a1');text(String(t.id+1),x-42,y-30,11,'#9b7049');if(dirty.has(t.id)){ellipse(x+12,y-25,18,9,'#a88e6155');ellipse(x-15,y-20,18,10,'#efe8d5');ellipse(x+17,y-20,18,10,'#eee5ce');text('TABAKLARI TOPLA',x,y-70,10,'#bc4934')}let c=customers.find(c=>c.table===t.id&&c.state==='eating');if(c){ellipse(x,y-22,25,13,'#fff3d7');wrap(x,y-27,.7)}}
